events.command:
/usr/bin/bash -lc "python --version; python - <<'PY'
mods=['numpy','scipy','pandas','statsmodels','rpy2']
for m in mods:
 try:
  mod=__import__(m); print(m, getattr(mod,'__version__','ok'))
 except Exception as e: print(m,'MISSING',str(e).splitlines()[0])
PY"

/usr/bin/bash -lc "printf '%s\\n' '---executables---'; for x in python3 Rscript perl ruby julia awk bc; do printf '%-8s' \""'$x"; command -v "$x" || true; done; printf '"'%s\\n' '---python3 modules---'; python3 --version 2>&1 || true; python3 - <<'PY'
mods=['numpy','scipy','pandas','statsmodels','rpy2']
for m in mods:
 try:
  mod=__import__(m); print(m, getattr(mod,'__version__','ok'))
 except Exception as e: print(m,'MISSING',str(e).splitlines()[0])
PY
printf '%s\\n' '---other DE tools---'; for x in galaxy_tool_util DESeq2 edgeR htseq-count featureCounts samtools; do command -v \""'$x" || true; done; find /usr /opt /root /codex_home -maxdepth 5 '"\\( -iname '*deseq*' -o -iname '*edger*' \\) 2>/dev/null | sed -n '1,100p'"

/usr/bin/bash -lc "/opt/conda/bin/python --version; /opt/conda/bin/python - <<'PY'
mods=['numpy','scipy','pandas','statsmodels','rpy2']
for m in mods:
 try:
  mod=__import__(m); print(m, getattr(mod,'__version__','ok'))
 except Exception as e: print(m,'MISSING',str(e).splitlines()[0])
PY
find /opt/conda/conda-meta -maxdepth 1 -type f | rg '/(r-|bioconductor|bioconda|pymc|numba)' | sed -n '1,100p'"
